<style>.flow{display:grid;grid-template-rows:auto minmax(0,1fr);gap:28px;height:calc(100vh - 130px);min-height:0}.stepper{border:0;border-radius:0;background:transparent;padding:0;margin:0}.stepper h3{display:none}.step-list{position:relative;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;align-items:start;padding-bottom:6px}.step-list::before{content:"";position:absolute;left:20px;right:20px;top:19px;height:2px;background:#d7dee8;z-index:0}.step-link{position:relative;z-index:1;display:grid;justify-items:center;gap:8px;padding:0 4px;border-radius:14px;color:#374151;background:transparent;text-align:center;text-decoration:none}.step-link.active{color:#14321f;font-weight:700}.step-index{width:38px;height:38px;border-radius:999px;border:1px solid #9ca3af;background:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700}.step-link.active .step-index{background:#389B5B;border-color:#389B5B;color:#fff}.step-label{font-size:.82rem;line-height:1.25;max-width:96px}.content{border:1px solid #e5e7eb;border-radius:20px;background:#fff;padding:18px;overflow:auto;min-height:0;margin-top:2px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.head h2{margin:0 0 12px;font-size:1.8rem}.head p{margin:6px 0 0;color:#6b7280}.top-actions{display:flex;gap:10px;flex-wrap:wrap}.btn,.next,.page-btn{display:inline-flex;align-items:center;gap:8px;text-decoration:none;border:1px solid #d1d5db;border-radius:12px;padding:10px 14px;background:#fff;color:#374151}.next{background:#389B5B;border-color:#389B5B;color:#fff}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:18px}.toolbar input{border:1px solid #d1d5db;border-radius:12px;padding:10px 12px;min-width:280px}.table{width:100%;border-collapse:collapse;margin-top:14px}.table th,.table td{padding:14px 10px;text-align:left;border-top:1px solid #edf0f2}.table th{font-size:.8rem;color:#6b7280;text-transform:uppercase;letter-spacing:.05em}.table-name-link{color:#0f172a;text-decoration:none;font-weight:600}.table-name-link:hover{color:#389B5B;text-decoration:underline}.filler-row td{height:56px;color:transparent;user-select:none}.empty{padding:22px 10px;color:#6b7280;text-align:center}.action-icons{display:flex;gap:10px}.icon-btn svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.8}.icon-btn{color:#111827}.icon-btn.delete{color:#ef4444}.bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:18px}.pager{color:#6b7280;font-size:.84rem}.pager-group{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.page-btn{align-items:center;justify-content:center;min-width:44px;height:44px;cursor:pointer;padding:0 14px;border-color:#d6e4d9;border-radius:14px;background:#f7fbf8;color:#2f4b36;font-weight:600;box-shadow:0 10px 24px rgba(56,155,91,.08)}.page-btn[disabled]{opacity:.45;cursor:not-allowed}.page-btn.is-active{background:#389B5B;border-color:#389B5B;color:#fff;box-shadow:0 14px 28px rgba(56,155,91,.22)}.page-numbers{display:flex;gap:10px;flex-wrap:wrap}@media(max-width:1100px){.stepper{padding:14px}.step-list{grid-template-columns:repeat(3,minmax(0,1fr))}.step-label{max-width:none}}</style>
<style>.flow{grid-template-rows:auto 1fr;min-height:calc(100dvh - 204px);height:auto;align-content:start;gap:24px}.step-list{gap:10px;padding-bottom:10px}.step-list::before{left:24px;right:24px;top:20px}.step-link{gap:10px;padding:0 6px}.step-index{width:40px;height:40px;font-size:.84rem}.step-label{font-size:.84rem;line-height:1.3;max-width:112px}.content{margin-top:0;overflow:visible;min-height:clamp(500px,calc(100dvh - 314px),780px);display:flex;flex-direction:column}.bottom{margin-top:auto;padding-top:18px}@media(max-width:1100px){.flow{min-height:auto}.content{min-height:auto}.step-label{max-width:none}}@media(max-width:760px){.content{padding:16px}}</style><div class="flow"><aside class="stepper"><div class="step-list"><?php foreach($steps as $index => $step): ?><a class="step-link<?php echo !empty($step['active']) ? ' active' : ''; ?>" href="<?php echo $esc($step['url']); ?>"><span class="step-index"><?php echo $index + 1; ?></span><span class="step-label"><?php echo $esc($step['label']); ?></span></a><?php endforeach; ?></div></aside><section class="content"><div class="head"><div><h2>Company List</h2><p>Select a current company to continue to its patient list.</p></div><div class="top-actions"><a class="btn" href="#">Import</a><a class="next" href="<?php echo $esc($newCompanyUrl); ?>">+ Add Company</a></div></div><div class="toolbar"><input id="companySearch" type="text" placeholder="Search company"></div><table class="table"><thead><tr><th>Company ID</th><th>Company Name</th><th>Registration No</th><th>Contact</th><th>Email</th><th>Action</th></tr></thead><tbody id="companyTableBody"><?php if($totalCompanies > 0): ?><?php foreach($companies as $company): ?><tr data-company-row="1"><td>#COM<?php echo $esc($company->company_id); ?></td><td><a class="table-name-link" href="<?php echo $esc(route('surveillance.patient', ['company_id' => $company->company_id])); ?>"><?php echo $esc($company->company_name); ?></a></td><td><?php echo $esc($company->mykpp_registration_no ?: '-'); ?></td><td><?php echo $esc($company->company_telephone ?: '-'); ?></td><td><?php echo $esc($company->company_email ?: '-'); ?></td><td><div class="action-icons"><a class="icon-btn" href="<?php echo $esc(route('surveillance.company.edit', ['id' => $company->company_id])); ?>" title="View"><svg viewBox="0 0 24 24"><path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6-10-6-10-6z"></path><circle cx="12" cy="12" r="3"></circle></svg></a><a class="icon-btn" href="<?php echo $esc(route('surveillance.company.edit', ['id' => $company->company_id])); ?>" title="Edit"><svg viewBox="0 0 24 24"><path d="M4 20h4l10-10-4-4L4 16v4z"></path><path d="M13 7l4 4"></path></svg></a><a class="icon-btn delete" href="<?php echo $esc(route('surveillance.company.delete', ['id' => $company->company_id, 'return_to' => $returnTo])); ?>"><svg viewBox="0 0 24 24"><path d="M4 7h16"></path><path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M6 7l1 13h10l1-13"></path><path d="M9 7V4h6v3"></path></svg></a></div></td></tr><?php endforeach; ?><?php else: ?><tr id="companyEmptyRow"><td class="empty" colspan="6">No company records found in the current database.</td></tr><?php endif; ?></tbody></table><div class="bottom"><span class="pager" id="companyPager"><?php echo $totalCompanies > 0 ? 'Showing 1-' . number_format($totalCompanies) . ' of ' . number_format($totalCompanies) . ' records' : 'Showing 0 of 0 records'; ?></span><div class="pager-group"><?php if($totalCompanies > 0): ?><button class="page-btn" id="companyPrevBtn" type="button">Previous</button><div class="page-numbers" id="companyPageNumbers"></div><button class="page-btn" id="companyNextBtn" type="button">Next</button><?php endif; ?></div></div></section></div><script>(function(){const search=document.getElementById('companySearch');const body=document.getElementById('companyTableBody');const rows=Array.prototype.slice.call(document.querySelectorAll('tr[data-company-row]'));const emptyRow=document.getElementById('companyEmptyRow');const pager=document.getElementById('companyPager');const prevBtn=document.getElementById('companyPrevBtn');const nextBtn=document.getElementById('companyNextBtn');const pageNumbers=document.getElementById('companyPageNumbers');if(!body||!pager||!rows.length){return;}const perPage=5;let currentPage=1;const fillerClass='filler-row';const clearFillers=function(){Array.prototype.slice.call(body.querySelectorAll('.'+fillerClass)).forEach(function(row){row.remove();});};const appendFillers=function(count){for(let i=0;i<count;i+=1){const filler=document.createElement('tr');filler.className=fillerClass;for(let col=0;col<6;col+=1){const cell=document.createElement('td');cell.innerHTML='&nbsp;';filler.appendChild(cell);}body.appendChild(filler);}};const getFilteredRows=function(){const term=(search&&search.value?search.value:'').trim().toLowerCase();if(!term){return rows;}return rows.filter(function(row){return (row.textContent||'').toLowerCase().indexOf(term)!==-1;});};const render=function(){clearFillers();const filtered=getFilteredRows();const total=filtered.length;const totalPages=Math.max(1,Math.ceil(total/perPage));if(currentPage>totalPages){currentPage=totalPages;}if(currentPage<1){currentPage=1;}rows.forEach(function(row){row.style.display='none';});const start=(currentPage-1)*perPage;const end=Math.min(start+perPage,total);const visibleRows=filtered.slice(start,end);visibleRows.forEach(function(row){row.style.display='';});if(emptyRow){emptyRow.style.display=total?'none':'';}if(total>0&&visibleRows.length<perPage){appendFillers(perPage-visibleRows.length);}pager.textContent=total?('Showing '+(start+1)+'-'+end+' of '+total+' records'):'Showing 0 of 0 records';if(prevBtn){prevBtn.disabled=currentPage===1||total===0;}if(nextBtn){nextBtn.disabled=currentPage===totalPages||total===0;}if(pageNumbers){pageNumbers.innerHTML='';for(let page=1;page<=totalPages;page+=1){const button=document.createElement('button');button.type='button';button.className='page-btn'+(page===currentPage?' is-active':'');button.textContent=String(page);button.addEventListener('click',function(){currentPage=page;render();});pageNumbers.appendChild(button);}}};if(search){search.addEventListener('input',function(){currentPage=1;render();});}if(prevBtn){prevBtn.addEventListener('click',function(){if(currentPage>1){currentPage-=1;render();}});}if(nextBtn){nextBtn.addEventListener('click',function(){if(currentPage<Math.max(1,Math.ceil(getFilteredRows().length/perPage))){currentPage+=1;render();}});}render();}());</script><?php medis_render_navigation_end(); ?></body></html>
